import sys
import os
import importlib.util

sys.path.append(os.path.join(os.path.dirname(__file__), 'src')) #make sure it refer to the good path for the src

from factory import SimulationBuilder


if len(sys.argv) < 2:
    raise SystemExit(" ! Error namelist missing. Usage : python HarP.py <input_filename>")
input_path = os.path.abspath(sys.argv[1])

# Load the namelist by file path rather than by module name, so it does not
# need to sit in HarP's own directory (or on sys.path/cwd) to be runnable -
# e.g. a namelist generated by a calling script into its own working
# directory. `__file__` inside the namelist then correctly points at its
# real location, which namelists can use to default their own output
# directory (see input.py's `diag_path`).
spec = importlib.util.spec_from_file_location(os.path.basename(input_path)[:-3], input_path)
if spec is None or spec.loader is None:
    raise SystemExit(f" ! Error: Could not find file '{input_path}'")
input_module = importlib.util.module_from_spec(spec)
spec.loader.exec_module(input_module)

sim=SimulationBuilder.build()
sim.run()
